# -*- coding: utf-8 -*-
"""Spread, stretch a step, pass through: individually authored explanations."""
import json
from pathlib import Path
from lesson_authoring import entry as E
P=[['拉丁 pandere / pandō','展开、伸开']]
EX=P+[['拉丁 ex- + pandere → expandere','向外展开'],['法语相关形式与拉丁借入 → 英语 expand','扩展、扩大、展开']]
STEP=P+[['拉丁 passus','伸开腿跨出的一步；步幅']]
PASS=STEP+[['通俗拉丁 *passāre → 古法语 passer → 英语 pass','迈步而过 → 经过、通过']]
COM=STEP+[['拉丁 com- + passus；通俗拉丁 *compassāre → 古法语 compas / compasser','一起计步、测量、绕行 → 圈、范围及测量工具'],['英语 compass','范围；圆规；罗盘']]
PAN=P+[['拉丁 pandiculārī → pandiculātus','伸展自己 → 伸展过的']]
def A(h,a,b):return h+[[a,b]]
W=[
E('expand','/ɪkˈspænd/','扩大；扩展；展开；详细说明','把折着的东西摊开，或让原来的边界往外移动：面积、业务、知识范围都能这样变大。','ex- 向外 + 拉丁 pandere“展开”，经法语和拉丁借词路线进入英语。',EX,'既能说 the company expanded，也能说 expand the business。expand on a point 是把一个观点展开讲，不是把观点推翻。数学里的 expand 则把式子按规则展开成等值表达式。','expand into；expand the range；expand on a point。','extend 常强调延长某个方向或期限；expand 常强调范围、体积或内容变大。expensive“昂贵”不是本词的形容词。',('The company plans to expand into new markets.','公司计划进入新的市场，扩大业务。'),('Could you expand on your last point?','你能把最后一点再详细讲讲吗？'),('Expanding (x + 1)² gives x² + 2x + 1.','把 (x + 1)² 展开，得到 x² + 2x + 1。'),sources=['https://www.etymonline.com/word/expand','https://en.wiktionary.org/wiki/expand#English']),
E('expansion','/ɪkˈspænʃən/','扩张；膨胀；扩建；展开','原来的边界被推开，这个向外变大的过程或新增部分就是 expansion。','拉丁 expānsiō，经法语 expansion 借入；与 expand 的 -pand- / -pans- 交替相关。',[P[0],['拉丁 expandere → expānsiō → 法语 expansion','展开 → 扩展过程'],['英语 expansion','扩张、膨胀、扩建等']],'可说 expansion of services，也可说 an expansion to a building。热膨胀、商业扩张和游戏扩展包使用同一空间画面，但不是彼此的历史先后链。','rapid expansion；thermal expansion；an expansion pack。','expansion 是扩大的过程或结果；expanse 是一大片展开的空间。两者结尾相似但搭配不同。',('The school’s expansion will add six classrooms.','学校扩建后将增加六间教室。'),('Thermal expansion can change the dimensions of a metal part.','热膨胀会改变金属零件的尺寸。')),
E('expansive','/ɪkˈspænsɪv/','广阔的；范围大的；健谈开朗的','空间舒展开来叫广阔；一个人的心情和谈话也向外打开，就显得健谈、热情。','拉丁 expāns- 是 expandere 的分词词干，接 -ive；现代与 expand / expansion 相连。',A(P,'拉丁 expandere / expāns- + -ive → expansive','向外展开 → 广阔；性情开朗舒展'),'an expansive view 是开阔景观；an expansive mood 是愿意多说、热情外露的心情。后者不是在说此人体型变大。','an expansive view；an expansive gesture；in an expansive mood。','expansive 是广阔、舒展的；expensive 是昂贵的。只差一个字母，却不属于同一个意义系统。',('The balcony offers an expansive view of the valley.','从阳台望出去，山谷景色十分开阔。'),('He was in an expansive mood and told us several stories.','他兴致很高，健谈地给我们讲了好几个故事。')),
E('expanse','/ɪkˈspæns/','一大片；辽阔区域','一片东西铺在眼前，你强调的是它铺开的范围，而不是它正在变大。','拉丁 expānsum，expandere 的分词形式作名词，进入英语。',[P[0],['拉丁 expandere → expānsum → 英语 expanse','展开 → 展开的一片区域']],'常说 an expanse of water、a vast expanse of sky。of 后接铺展的物质或区域；一个小封闭房间一般不容易让人想到 expanse。','a vast expanse；an expanse of snow；an open expanse。','space 可以只是空处；expanse 常让人感到一整片宽广、延伸的景象。',('A wide expanse of water lay beyond the trees.','树木后面是一大片宽阔的水面。'),('The snow formed an unbroken expanse of white.','积雪铺成了连绵不断的一片白色。')),
E('expandable','/ɪkˈspændəbəl/','可扩大的；可扩展的','东西现在有一个大小，但设计上留了继续撑开、增加容量的余地。','expand + -able“能够……的”。',A(EX,'英语 expand + -able → expandable','扩展 → 可以扩展的'),'可形容行李箱、存储容量或界面区域。expandable storage 说可以增加存储能力，具体能加多少、怎样加，要由产品条件说明，词本身不保证无限。','expandable storage；an expandable suitcase；an expandable section。','expanded 是已经扩大；expandable 是能够扩大。expanded storage 与 expandable storage 描述不同状态。',('The suitcase has an expandable section for extra clothes.','行李箱有一个可以扩大的夹层，用来多装些衣服。'),('The device offers expandable storage.','这台设备支持扩展存储空间。')),
E('expander','英 /ɪkˈspændə/；美 /ɪkˈspændər/','扩展器；使扩大的人或装置','在 expand 后加 -er，把“谁或什么让它展开”单独叫出来。','expand + -er，表示执行扩展功能的人或事物。',A(EX,'英语 expand + -er → expander','扩展 → 使扩展的装置、工具等'),'不同领域的对象不同：界面里的 expander 展开隐藏内容，音频 expander 扩大信号动态范围。先看它展开的究竟是什么，不要把所有场景都译成同一种机械。','an audio expander；a panel expander；a port expander。','expander 是起作用的东西；expansion 是变化过程或结果。-er 也可以表示机器，不只表示职业。',('Click the expander to reveal the advanced settings.','点击展开控件，显示高级设置。'),('The port expander provides additional connections.','接口扩展器提供了更多连接端口。')),
E('expansionism','/ɪkˈspænʃənɪzəm/','扩张主义','把向外扩展变成一种持续追求的政策，常指扩大国家领土、权力或影响。','expansion + -ism，形成表示政策、倾向的名词。',A(EX,'英语 expansion → expansionism','扩展 → 以扩张为目标的政策或倾向'),'历史、政治讨论中常见 territorial expansionism。词语经常带批评，但应根据具体行动说明扩张内容，而不是把所有经济增长都叫扩张主义。','territorial expansionism；military expansionism；a policy of expansionism。','expansion 是一般扩大；expansionism 将其提升为一种政策或主张，政治色彩更强。',('The chapter examines territorial expansionism in the nineteenth century.','这一章研究十九世纪的领土扩张主义。'),('The historian distinguishes trade growth from political expansionism.','历史学者区分了贸易增长与政治扩张主义。')),
E('expansionist','/ɪkˈspænʃənɪst/','扩张主义的；扩张主义者','-ist 可以是持这种主张的人，也可以用来修饰该主张推动的政策。','expansion + -ist；与 expansionism 对应。',A(EX,'英语 expansion → expansionist','扩展 → 主张扩张的人或扩张政策的'),'an expansionist policy 修饰政策；an expansionist 可指主张这种政策的人。一般商业扩张未必需要用这个带政治意味的词。','an expansionist state；expansionist ambitions；an expansionist policy。','expansive 可说宽广或健谈；expansionist 说扩张的政策立场。健谈的人不是因此就成了 expansionist。',('The document reveals the government’s expansionist ambitions.','文件显示了该政府的扩张野心。'),('The debate divided expansionists from their opponents.','这场辩论把扩张主义者与反对者分成了两方。')),
E('expansionary','英 /ɪkˈspænʃənəri/；美 /ɪkˈspænʃəneri/','促进扩张的；扩张性的〔常用于经济政策〕','一项政策的方向是把经济活动或总需求往上推，因此被称为 expansionary。','expansion + -ary，表示相关性质或作用。',A(EX,'英语 expansion → expansionary','扩张 → 促进扩张的'),'常见 expansionary fiscal policy 与 expansionary monetary policy。它说明政策意图或方向，不保证每次都达到预期增长，也不是国际政治中的领土扩张。','expansionary policy；an expansionary budget；expansionary measures。','expansionist 常谈政治扩张主义；expansionary 常谈使经济活动扩大的政策作用。',('The textbook describes the budget as expansionary.','教材把这份预算描述为扩张性的。'),('The lecture compared expansionary and contractionary monetary policies.','讲座比较了扩张性与紧缩性货币政策。')),
E('expansivity','/ˌekspænˈsɪvəti/','膨胀性；膨胀系数〔依学科语境〕；扩张性','不只说它会变大，而是把“多容易扩大、扩大多少”当成一种可比较的性质。','expansive 去 e 接 -ity；与 expansion 的扩大意义相连。',A(EX,'英语 expansive → expansivity','有扩张性的 → 扩张性质或相关量'),'物理语境可指热膨胀相关系数，应分清线膨胀与体积膨胀等定义。动力系统里也有专门定义，涉及不同轨道能否在某次迭代拉开一定距离，不能直接当热学量。','thermal expansivity；volumetric expansivity；the expansivity of a material。','expansion 是一次实际变化；expansivity 常表示描述这种变化倾向的性质或参数。',('The table compares the thermal expansivity of several materials.','表格比较了几种材料的热膨胀性质。'),('The author defines expansivity before stating the theorem.','作者在陈述定理之前先定义了扩张性。')),
E('pace','常用 /peɪs/；另源书面介词 /ˈpɑːtʃeɪ/ 等','步子；速度；节奏；踱步；控制速度','从迈出一步，走到一步接一步的快慢，再走到工作、变化和生活的节奏。','常用词接拉丁 passus“一步”，经法语 pas；书面 pace“恕我不同意”则来自拉丁 pāx“和平”的变格，另源。',STEP+[['古法语 pas → 英语 pace /peɪs/','一步 → 步速、节奏；也作动词'],['并列的另一源：拉丁 pāx → pāce → 英语书面 pace','此线不接前面的步伐词；和平、获准 → 表示有礼貌地提出不同意见']],'keep pace with 是跟上；pace yourself 是分配体力、控制节奏；pace the room 是来回踱步。另源的书面介词用于礼貌反驳，不能译成 according to“根据”。','at your own pace；keep pace with；pace yourself；pace the room。','speed 偏速度数值；pace 还强调做事推进的节奏。pace oneself 不是一味追求快。',('Work at your own pace, but check your progress regularly.','按自己的节奏工作，但要定期检查进度。'),('He paced the corridor while waiting for the news.','他等待消息时在走廊里来回踱步。'),('Pace the earlier critic, the ending is not entirely predictable.','恕我不同意先前那位评论者，这个结局并非完全可以预料。'),sources=['https://www.etymonline.com/word/pace']),
E('compass','/ˈkʌmpəs/','罗盘；指南针；圆规；范围','它早先连着绕圈、计步和划定范围。画圆的工具与辨方向的工具后来共享这个名字。','com- + 拉丁 passus“一步”，经计步、绕行相关形式进入古法语 compas / compasser，再进英语。',COM,'看方向的 compass 常见单数；画圆工具可说 a compass，也可说 a pair of compasses。magnetic compass 指磁罗盘，所指磁北不必等于地理真北。moral compass 借方向工具比喻价值判断。','a magnetic compass；a pair of compasses；a moral compass；within the compass of。','compass 不是因为能“压缩”而得名；不要和 compress 混淆。encompass 则保留了围成范围的方向。',('They used a compass to check their direction.','他们用罗盘确认方向。'),('Use a pair of compasses to draw the circle.','用圆规画这个圆。'),('She regards fairness as her moral compass.','她把公平看作自己判断是非的准绳。'),sources=['https://www.etymonline.com/word/compass']),
E('encompass','/ɪnˈkʌmpəs/','包含；涵盖；包围','在一组事物外面画一个大圈，让它们全部落进圈内，这就是涵盖。','en- + compass；compass 的围绕、范围义发展成动词。',A(COM,'英语 en- + compass → encompass','围在范围内 → 包围、涵盖'),'现代常用于范围说明：a course encompasses several topics。它强调覆盖到哪些内容，比 contain 更容易让人想到较大的范围或多种类别。','encompass a range of；encompass several areas；encompass the whole。','include 可举其中一部分；encompass 常强调较全面地包进范围。是否真全面仍看上下文。',('The course encompasses history, language and literature.','这门课程涵盖历史、语言和文学。'),('The park encompasses both woodland and open grassland.','公园范围包括林地和开阔草地。')),
E('encompassment','/ɪnˈkʌmpəsmənt/','包围；涵盖；包容关系〔较少用〕','把“画圈并包在里面”这件事变成名词，讨论这种覆盖或包含关系本身。','encompass + -ment，表示行为、状态或结果。',A(COM,'英语 encompass → encompassment','涵盖、围住 → 涵盖状态或过程'),'多见于较抽象的讨论。普通表达中，coverage、inclusion 或直接用 encompass 往往更顺口；人类学等学科有自己的专门用法，需按作者定义读。','the encompassment of；complete encompassment；hierarchical encompassment。','encompassment 不等于 imprisonment“监禁”；被包含在范围内与被限制自由是不同事情。',('The essay discusses the encompassment of local traditions within a national narrative.','文章讨论了地方传统如何被纳入国家叙事。'),('The author uses encompassment to describe the relation between a whole and its parts.','作者用 encompassment 描述整体与各部分之间的关系。')),
E('spawn','英 /spɔːn/；美 /spɔːn, spɑːn/','产卵；卵；引发；大量产生；生成〔游戏、计算机〕','鱼把许多卵散到水中，从“向外散开”形成产卵，再借来表示不断生出新事物。','拉丁 expandere，经法语 espandre / espaundre 进入中古英语 spawnen；与 expand 是同源但路线不同的词。',[P[0],['拉丁 expandere → 古法语 espandre；盎格鲁法语 espaundre','展开、散出 → 鱼产卵'],['中古英语 spawnen → spawn','产卵；引发或生成许多东西']],'spawn new ideas 可说催生想法；游戏里 spawn an enemy 是生成敌方角色。蘑菇栽培里的 spawn 是用于繁殖的菌丝种料，不是鱼卵。称人的孩子为 spawn 常带贬损或戏谑，别随意用。','spawn new problems；fish spawn；a spawn point；mushroom spawn。','hatch 是卵孵化；spawn 是产卵或生成。spawn 的游戏义也不一定意味着复活，重新生成常用 respawn。',('The fish return to the river to spawn.','这些鱼回到河里产卵。'),('The discovery spawned a new line of research.','这项发现催生了一条新的研究方向。'),sources=['https://www.etymonline.com/word/spawn','https://en.wiktionary.org/wiki/spawn#English']),
E('impasse','英 /ˈæmpɑːs/；美 /ˈɪmpæs/','僵局；无路可走的局面','走进一条没有出口的路，向前走不了；谈判也可能卡到这一步。','法语 im- 不 + passe“通行”，接 passer；英语整体借入 impasse。',A(PASS,'法语 im- + passe → impasse → 英语','不通的路 → 僵局'),'reach an impasse 表示谈到卡住；break the impasse 表示找到突破口。它通常是进展受阻的局面，不只是某一方心情不好。','reach an impasse；break an impasse；a political impasse。','deadlock 与之接近；impassable 则是形容路或障碍无法通过。impasse 是名词，不能说 the road is impasse。',('The talks reached an impasse over the cost.','谈判在费用问题上陷入僵局。'),('A new proposal helped break the impasse.','一项新提议帮助打破了僵局。'),sources=['https://www.etymonline.com/word/impasse']),
E('impassable','英 /ɪmˈpɑːsəbəl/；美 /ɪmˈpæsəbəl/','无法通过的；无法通行的','路还在，但积雪、洪水或障碍把“走过去”的可能性堵住了。','im- 不 + passable“可以通过的”；pass + -able。',A(PASS,'英语 pass → passable；im- + passable → impassable','可通行 → 无法通行'),'常形容道路、山口或河流。强调在当前条件下无法通过，不表示它永远不可能被修好。','an impassable road；render a route impassable；become impassable。','impassible 是不受痛苦或情感影响的另一个词，接“承受”词族；不要与 impassable 的“通过”混淆。',('Heavy snow made the mountain road impassable.','大雪使山路无法通行。'),('The route becomes impassable after prolonged rain.','长时间下雨后，这条路线就走不通了。')),
E('passus','/ˈpæsəs/','叙事诗的一节；篇章的一部分〔文学术语〕','读一部长篇像走一段路，每一节就是迈进的一步；这个分节名称保留了拉丁“一步”。','拉丁 passus“一步”→ 中世纪拉丁“书或文献中的一段”→ 英语文学术语。',A(STEP,'中世纪拉丁 passus → 英语 passus','一步 → 作品的一节'),'常在中世纪作品及其研究中出现，不必把所有现代章节都改叫 passus。复数可仍作 passus，也可用 passuses，按所用版本习惯。','the first passus；a passage in this passus；each passus。','passage 是常见的文章一段；passus 是特定文学分节名称。它不是 passion“激情”的缩写。',('The first passus introduces the central question of the poem.','诗的第一节提出了核心问题。'),('The commentary discusses the imagery in this passus.','评注讨论了这一节中的意象。'),sources=['https://www.merriam-webster.com/dictionary/passus']),
E('dispand','参考读法 /dɪˈspænd/','展开；扩展〔古旧〕','把聚在一起的东西向外散开、摊开；可以把它当作 expand 的古旧近亲来认。','拉丁 dis- 分开 + pandere 展开 → dispandere，英语借入。',A(P,'拉丁 dis- + pandere → dispandere → dispand','分开铺展 → 展开'),'主要用于读旧文，现代普通表达用 spread 或 expand。dis- 在这里参与“向外分开”，并不是否定动作，所以不是“取消展开”。','dispand the wings〔旧式〕；dispand outward〔旧式〕。','disband 是解散团体，拼写相近却不是本词。dispand 的 p 提醒你连着 pandere“展开”。',('The old description says that the bird began to dispand its wings.','那段旧式描写说，鸟开始展开翅膀。'),('In this passage, dispand simply means to spread outward.','在这一段里，dispand 只是向外展开的意思。'),sources=['https://en.wiktionary.org/wiki/dispand#English']),
E('dispansion','参考读法 /dɪˈspænʃən/','展开；扩散〔古旧〕','把 dispand 的向外展开变成过程名词，类似更常见的 expansion。','dispand + -sion，对应 pand- / pans- 的词干交替。',A(P,'拉丁 dispandere → 英语 dispand → dispansion','展开 → 展开的行为或状态'),'主要是旧词识读项，不宜为了显得正式而替换日常 expansion。-sion 表过程，读音尾部通常为 /ʃən/。','the dispansion of；a process of dispansion〔旧式〕。','dispersion 是散布、分散，现代更常见，但来源和具体专业用法不能直接当作本词的拼写变体。',('The editor glosses dispansion as expansion.','编辑把 dispansion 解释为展开。'),('The passage describes the dispansion of the material.','这段文字描述了材料向外展开的过程。'),sources=['https://en.wiktionary.org/wiki/dispansion#English']),
E('pandiculate','/pænˈdɪkjəleɪt/','舒展身体；伸懒腰〔专门、少用〕','醒来后把躯干和四肢一起伸展开，常伴着哈欠；这个日常动作有一个不日常的长名字。','拉丁 pandiculātus，接 pandiculārī“伸展自己”，再接 pandere“展开”。',A(PAN,'英语 pandiculate','做伸懒腰般的舒展动作'),'重点是身体整体的自然伸展，普通交流说 stretch 通常就够了。它常描写醒来时自然做出的伸展，与有计划地练柔韧性的 stretching 不完全重合。','pandiculate on waking；stretch and pandiculate。','yawn 是打哈欠，pandiculate 是身体伸展；二者常一起发生，但不能完全画等号。',('After waking, the cat paused to pandiculate.','醒来后，猫停下来伸了个懒腰。'),('The article uses pandiculate for the familiar act of stretching on waking.','文章用 pandiculate 称呼醒来伸懒腰这个熟悉的动作。'),sources=['https://www.merriam-webster.com/medical/pandiculation','https://en.wiktionary.org/wiki/pandiculate#English']),
E('pandiculation','/pænˌdɪkjəˈleɪʃən/','伸懒腰；困倦或醒来时的身体舒展','把躯干、四肢一起伸直、绷起再舒展开，这整个动作或现象就叫 pandiculation。','拉丁 pandiculāt- 的伸展词干 + 名词后缀；与英语 pandiculate 对应。',A(PAN,'英语 pandiculation','身体舒展的动作、现象'),'常见于生理行为描述。它常伴哈欠，但哈欠是嘴部和呼吸的动作，pandiculation 说的是躯干和四肢的舒展。','pandiculation on waking；yawning and pandiculation。','stretching 范围更广；pandiculation 常专指困倦或醒来时那种伸展、绷紧身体的动作。',('Pandiculation is often accompanied by a yawn.','伸懒腰常常伴随着哈欠。'),('The researcher recorded bouts of pandiculation after the animals woke.','研究者记录了动物醒来后一阵阵伸懒腰的动作。'),sources=['https://www.merriam-webster.com/medical/pandiculation']),
E('repand','/rɪˈpænd/','边缘微波状的；向后或向上弯的〔植物等形态描述〕','沿着叶片边缘看，边线不是锯齿，而是轻轻起伏的浅波浪。','拉丁 repandus，表示展开或弯曲的形状。词典对更早接 repandere“展开”还是 pandus“弯的”有不同说明。',[['拉丁 repandus','展开、回弯等形态；更早分析有差异'],['英语 repand','尤其指边缘浅浅起伏']],'常修饰叶缘，也可用于其他形态描述。它说明的是形状，不能机械译为“再展开一次”，更不能凭名称推断叶片形成过程。','a repand margin；repand leaves；a repand outline。','serrated 是锯齿状；repand 是较浅的波状起伏。植物学近邻术语界限仍以具体检索表为准。',('The specimen has broad leaves with repand margins.','这个标本的叶片宽大，边缘浅浅起伏。'),('The guide distinguishes a repand edge from a sharply toothed one.','指南区分了微波状边缘与明显齿状边缘。'),sources=['https://www.merriam-webster.com/dictionary/repand','https://en.wiktionary.org/wiki/repand#English']),
E('subrepand','参考读法 /ˌsʌbrɪˈpænd/','略呈微波状边缘的〔植物形态〕','sub- 把程度再往下调一点：边缘有起伏的意思，但还不明显。','sub- 近于、稍微 + repand；现代学术构词。',[['拉丁 repandus → 英语 repand','边缘微波状的'],['sub- + repand → subrepand','近于微波状、略呈波状']],'多用于植物描述与检索表，sub- 此处表示程度接近或略微，不是空间上的“叶子下面”。具体观察仍要看该资料的术语定义。','a subrepand margin；subrepand leaves。','subrepand 与 repand 的区别在程度：前者的波状更轻。这里 sub- 说“稍微”，不是“在下方”。',('The description calls the leaf margin subrepand.','描述把叶缘称为略呈微波状。'),('Under magnification, the subrepand edge shows shallow undulations.','放大观察时，略呈微波状的边缘显出浅浅起伏。'),sources=['https://en.wiktionary.org/wiki/subrepand#English']),
]
W += [
E('pass','英 /pɑːs/；美 /pæs/','经过；通过；递给；超过；通行证；山口','先抓住“从这一边走到另一边”：人经过门口，球递到队友，考试越过及格线，时间走到身后。','拉丁 passus“一步”→ 通俗拉丁 *passāre → 古法语 passer → 英语 pass；部分名词另经法语 pas 或由英语动词产生。',PASS,'pass an exam 是通过考试；pass someone the salt 是把盐递给某人；pass a law 是通过法律；a mountain pass 是山间可通过之处。I’ll pass 可表示这次不参加，源于轮次活动中让机会过去的用法。','pass through；pass an exam；pass the time；a boarding pass。','passed 是动词过去式；past 可作“过去的、经过”等。He passed the shop 与 He walked past the shop 结构不同。',('Could you pass me the salt?','你能把盐递给我吗？'),('She passed the exam on her second attempt.','她第二次参加考试时通过了。'),('The hikers crossed a narrow mountain pass.','徒步者穿过了一道狭窄的山口。'),sources=['https://www.etymonline.com/word/pass']),
E('passage','/ˈpæsɪdʒ/','通道；经过；航程；文章或音乐的一段','人通过一条通道，时间经过一段历程，阅读也从一段文字走向下一段。这些义项共享“经过一段”的联系。','古法语 passage，接 passer“通过”，借入中古英语；不是单纯把现代英语 pass 后临时加 -age。',STEP+[['通俗拉丁 *passāre → 古法语 passer → passage','迈步、通过 → 通过的过程、路径'],['英语 passage','通道；航程；文字、音乐片段等']],'a narrow passage 是窄通道；a passage from a novel 是小说中的一段；the passage of time 是时间流逝。文章段落可以不恰好等于一个 paragraph。','a passage from；the passage of time；a narrow passage；safe passage。','paragraph 是排版或结构上的段落；passage 是选取的一段内容，可以横跨几个段落。',('A narrow passage connects the two courtyards.','一条狭窄通道连接着两个院子。'),('Read the passage and explain why the narrator leaves.','读这段文字，解释叙述者为什么离开。'),('The passage of time changed their understanding of the event.','随着时间流逝，他们对这件事的理解发生了变化。')),
E('passenger','英 /ˈpæsɪndʒə/；美 /ˈpæsɪndʒər/','乘客；旅客','最早是行路、经过的人，后来收窄为坐在交通工具里、由别人驾驶载着走的人。','古法语 passagier，接 passage；英语早期 passager 后来插入 n，成为 passenger。',STEP+[['古法语 passer → passage → passagier','经过 → 行程 → 行旅者'],['中古英语 passager → passenger','加入 n → 现代主要指乘客']],'乘客通常区别于驾驶员或负责运营的机组、船员。私人汽车里的同行者也是 passenger，不是一定要买票才算。中间的 -nger 不是一个独立表示乘客的词根。','a passenger train；the passenger seat；airline passengers。','traveller 是旅行的人，范围更广；passenger 关注他在交通工具中被运送的身份。',('The passenger in the front seat checked the map.','前排的乘客查看了地图。'),('All passengers were asked to remain seated.','所有乘客都被要求继续坐在座位上。'),sources=['https://www.etymonline.com/word/passenger']),
E('passport','英 /ˈpɑːspɔːt/；美 /ˈpæspɔːrt/','护照；通向某事的条件或凭借〔比喻〕','词里保留了“获准通过口岸”的旧画面，后来成为跨境旅行时识别持有人身份的重要证件。','法语 passeport：passer“通过”的形式 + port“港口、出入境口岸”；英语整体借入。',STEP+[['古法语 passer + port → passeport','通过口岸的许可'],['英语 passport','护照；比喻为通向某结果的凭借']],'普通义指护照；a passport to success 把证件比作进入机会的凭借。护照与签证是不同概念，不能在翻译中混为一张证件。','a valid passport；renew a passport；a passport to opportunity。','port 这里是口岸，不是 portable 中“搬运”的词根。记忆用“通过口岸”，不硬拆成“搬运通行”。',('She kept her passport in a secure pocket.','她把护照放在一个安全的口袋里。'),('The qualification was seen as a passport to better opportunities.','这项资质被视为通向更好机会的凭借。'),sources=['https://www.etymonline.com/word/passport']),
E('bypass','英 /ˈbaɪpɑːs/；美 /ˈbaɪpæs/','绕过；避开；绕行道路；旁路','正路堵着或太绕，就另开一条路从旁边过去；这个画面适用于道路、管道和办事流程。','by“在旁边” + pass；由从旁边通过的表达形成动词、名词。',A(PASS,'英语 by + pass → bypass','从旁经过 → 绕过；旁路'),'a bypass 可指绕过城镇的道路；bypass a step 是跳过步骤。医疗中的 bypass 也用另建路径的画面命名，例如让血液绕过原先受阻的路线。','bypass the town；bypass a step；a road bypass；a bypass route。','detour 常是临时绕行；bypass 也可以是专门修好的固定旁路。绕过某人办事还可能含有越过其权限的意思。',('The new road bypasses the town centre.','新路绕过了市中心。'),('The shortcut lets experienced users bypass the introductory screen.','这个快捷方式让熟练用户跳过介绍页面。'),sources=['https://www.etymonline.com/word/bypass','https://en.wiktionary.org/wiki/bypass#English']),
E('surpass','英 /səˈpɑːs/；美 /sərˈpæs/','超过；胜过；超出预期','不是刚好走到标准线，而是穿过它、继续到前面，所以结果比原先更高、更好或更多。','法语 sur- 超过 + passer 经过 → surpasser，再借入英语。',STEP+[['法语 passer → sur- + passer → surpasser','通过 → 超越'],['英语 surpass','超过数量、水平或预期']],'直接接被超过的对象：surpass expectations、surpass a record。重点常是超出某个基准，既可数量，也可质量。','surpass expectations；surpass a previous record；surpass oneself。','surpass 往往强调胜过基准；pass 可以只是通过或从旁经过。pass an exam 不等于 surpass an exam。',('The results surpassed our expectations.','结果超出了我们的预期。'),('This year’s attendance surpassed the previous record.','今年的到场人数超过了此前纪录。'),sources=['https://www.etymonline.com/word/surpass']),
E('past','英 /pɑːst/；美 /pæst/','过去；过去的；超过；经过','已经走过身边的时间、位置或阶段，就落在 past 这一侧。','中古英语 pass 的过去分词 passed 的变体，后来独立成 past，用于形容词、名词、介词等。',A(PASS,'中古英语 passed → past','已经经过 → 过去的；经过某位置'),'in the past 是在过去；walk past the shop 是从商店旁走过；half past two 是两点半。现代 past 通常不承担 pass 的动词过去式功能。','in the past；past experience；walk past；half past。','He passed the shop 中 passed 是动词；He walked past the shop 中 past 指经过的位置。两者常同音，写法看语法。',('She walked past the station without noticing it.','她从车站旁走过，却没有注意到。'),('We can learn from the past without repeating it.','我们可以从过去学习，而不重演过去。'),('It is already half past six.','已经六点半了。'),sources=['https://www.etymonline.com/word/past']),
E('passing','英 /ˈpɑːsɪŋ/；美 /ˈpæsɪŋ/','经过的；短暂的；顺便的；流逝；去世〔委婉语〕','东西只是从眼前经过，没有长期停留，于是可以说短暂兴趣、顺便提及或时间流逝。','pass + -ing，分词、形容词和名词用法逐渐展开。',A(PASS,'英语 pass + -ing → passing','经过 → 短暂；流逝；死亡的委婉表达'),'in passing 是顺便、一带而过；a passing interest 是短暂兴趣。someone’s passing 可委婉指去世；a passing grade 则是达到及格标准的成绩，不能只按短暂理解。','in passing；a passing interest；the passing of time；a passing grade。','passing 不一定等于过去的，past 才常表达已过去的时间。a passing car 是正在经过的车。',('She mentioned the problem only in passing.','她只是顺便提到了这个问题。'),('What began as a passing interest became a lifelong hobby.','起初短暂的兴趣后来变成了终身爱好。'),('The family thanked everyone for their support after his passing.','他去世后，家人感谢大家给予的支持。')),
E('expansively','/ɪkˈspænsɪvli/','开阔地；大幅度地；健谈热情地','动作像打开双臂一样放开，或谈话热情地铺展开来。','expansive + -ly；保留宽广与性情开放两条意思。',A(EX,'英语 expansive + -ly → expansively','舒展、开阔的 → 以舒展或热情的方式'),'gesture expansively 是作宽大的手势；speak expansively 可说热情而详细地谈论。不要误看成 expensively“花费昂贵地”。','gesture expansively；speak expansively；think expansively。','extensively 常说范围广、做得多；expansively 还可以表达人的热情与舒展姿态。',('He gestured expansively towards the open valley.','他大幅张开手臂，指向开阔的山谷。'),('She spoke expansively about her plans for the garden.','她兴致勃勃地详细谈起了自己的花园计划。'),sources=['https://www.merriam-webster.com/dictionary/expansive']),
E('expansiveness','/ɪkˈspænsɪvnəs/','辽阔；开阔感；健谈大方','一片空间让人觉得铺展开了，一个人的性情也可能让人觉得不拘束、愿意交流。','expansive + -ness，形容词变性质名词。',A(EX,'英语 expansive + -ness → expansiveness','宽广、开放的 → 宽广感或开放的性情'),'可以说 the expansiveness of the landscape，也能说 someone’s expansiveness。后者不是精确测量人格的指标，而是描述当时或惯常的开放、热情气质。','a sense of expansiveness；the expansiveness of a view；unusual expansiveness。','expansion 是实际扩大的过程；expansiveness 是宽广或开放的性质。房间没变大，也能因视野而有开阔感。',('The low walls preserved the garden’s sense of expansiveness.','低矮的围墙保留了花园的开阔感。'),('His unusual expansiveness surprised the quiet guests.','他不同寻常的健谈热情让安静的客人们吃了一惊。'),sources=['https://www.merriam-webster.com/dictionary/expansive']),
]
